{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "apps_json": [
      {
        "name": "Click Season Desk",
        "description": "Clickable season rows, revisions, and chart",
        "tabs": [
          {
            "id": "season",
            "name": "Season",
            "layout": [
              {
                "i": "click_season_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              },
              {
                "i": "estimate_revisions",
                "x": 20,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          {
            "id": "chart",
            "name": "Chart",
            "layout": [
              {
                "i": "earnings_chart",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        ],
        "groups": [
          {
            "name": "Click Season Sync",
            "type": "param",
            "paramName": "symbol",
            "widgetIds": [
              "click_season_table",
              "estimate_revisions",
              "earnings_chart"
            ]
          }
        ]
      }
    ],
    "widgets_json": {
      "click_season_table": {
        "name": "Click Season Table",
        "description": "Season rows whose symbol cell syncs revisions",
        "endpoint": "/click-season-table",
        "type": "table",
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "symbol",
                "headerName": "Symbol",
                "cellDataType": "text",
                "formatterFn": "titleCase",
                "renderFn": "cellOnClick",
                "renderFnParams": {
                  "actionType": "groupBy",
                  "groupByParamName": "symbol"
                }
              },
              {
                "field": "revision_pct",
                "headerName": "Revision %",
                "cellDataType": "number",
                "formatterFn": "percent"
              }
            ]
          }
        }
      },
      "estimate_revisions": {
        "name": "Estimate Revisions",
        "description": "Street estimate revisions by quarter",
        "endpoint": "/estimate-revisions",
        "type": "table",
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "quarter",
                "headerName": "Quarter",
                "cellDataType": "text"
              },
              {
                "field": "eps_estimate",
                "headerName": "EPS Est",
                "cellDataType": "number"
              },
              {
                "field": "revenue_estimate_b",
                "headerName": "Revenue Est ($B)",
                "cellDataType": "number"
              }
            ]
          }
        }
      },
      "earnings_chart": {
        "name": "EPS History",
        "description": "Plotly EPS beat/miss history",
        "endpoint": "/eps-history",
        "type": "chart",
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "chart": {
            "type": "chart-plotly",
            "raw": true
          }
        }
      }
    }
  }
}

